use core { audit, audit_table, audit_tag }

table orders {
  id i64 identity
  audit_seq i64
  primary key (id)
  index ix_orders_audit (audit_seq)
  foreign key fk_orders_audit (audit_seq) references audit (seq) on delete restrict on update restrict
  settings {
    audit into order_history column audit_seq references audit action change previous previous_audit_seq tables audit_table (audit_seq, table_name)
  }
}

table order_history {
  history_id i64 identity
  change varchar(8)
  previous_audit_seq i64 null
  id i64
  audit_seq i64
  primary key (history_id)
}

